  const addN = ' style="mix-blend-mode:plus-lighter"';
  const lerp = function (p, q, t) { return p + (q - p) * t; };
  const x0 = o.W - 129, y0 = 30, ww = 56, wh = 66, x1 = x0 + ww, y1 = y0 + wh, xm = x0 + ww / 2, yb = y0 + wh * 0.45;
