      '<ellipse cx="' + f(x + w * 0.5) + '" cy="' + f(y + w * 0.05) + '" rx="' + f(w * 0.5) + '" ry="' + f(w * 0.07) + '"/>' +
      '<ellipse cx="' + f(x + w * 0.32) + '" cy="' + f(y - w * 0.02) + '" rx="' + f(w * 0.2) + '" ry="' + f(w * 0.12) + '"/>' +
      '<ellipse cx="' + f(x + w * 0.56) + '" cy="' + f(y - w * 0.07) + '" rx="' + f(w * 0.2) + '" ry="' + f(w * 0.16) + '"/></g>';
